<?php require_once dirname(__DIR__,2).'/bootstrap.php';$id=(int)($_GET['id']??0);v17_content('recording',$id,current_user());$r=v17_query('SELECT r.*,u.username,u.display_name,u.avatar_url,s.category,s.description FROM recordings r JOIN users u ON u.id=r.user_id JOIN streams s ON s.id=r.stream_id WHERE r.id=?',[$id])->fetch();v17_query('UPDATE recordings SET view_count=view_count+1 WHERE id=?',[$id]);$r['view_count']++;json_response(['recording'=>v17_recording($r)]);